import sys

def solve():
    input = sys.stdin.read
    data = input().split()

    iterator = iter(data)
    try:
        n = int(next(iterator))
        m = int(next(iterator))
    except StopIteration:
        return

    exams = []
    exam_days = [0] * (n + 1)  # To mark which exam is on which day (1-based index)

    for i in range(1, m + 1):
        s = int(next(iterator))
        d = int(next(iterator))
        c = int(next(iterator))
        exams.append({'id': i, 's': s, 'd': d, 'c': c, 'rem': c})
        exam_days[d] = i

    schedule = [0] * (n + 1)  # 1-based index for days

    # Iterate through each day from 1 to n
    for day in range(1, n + 1):
        # If this day is an exam day, mark it
        if exam_days[day] != 0:
            exam_id = exam_days[day]
            schedule[day] = exam_id + 1  # Output format: m+1 for exam days
            continue

        # Find valid exams to prepare for on this day
        # Valid if: s_i <= day < d_i and rem > 0
        candidates = []
        for idx, exam in enumerate(exams):
            if exam['rem'] > 0:
                if exam['s'] <= day < exam['d']:
                    candidates.append(idx)

        if not candidates:
            continue

        # Greedy choice: pick the exam with the earliest deadline (d_i)
        # If deadlines are equal, any order is fine, but let's be deterministic by picking the first one found with min d
        best_idx = -1
        min_d = float('inf')

        for idx in candidates:
            if exams[idx]['d'] < min_d:
                min_d = exams[idx]['d']
                best_idx = idx

        # Assign this day to the chosen exam
        if best_idx != -1:
            schedule[day] = exams[best_idx]['id']
            exams[best_idx]['rem'] -= 1

    # Check if all exams are prepared
    possible = True
    for exam in exams:
        if exam['rem'] > 0:
            possible = False
            break

    if not possible:
        print("-1")
    else:
        # Print schedule from day 1 to n
        print(*(schedule[1:]))

if __name__ == "__main__":
    solve()
